/**
 * The row and disc glyphs, now delegates to the generated icon set.
 *
 * Come alive (founder decision D11) replaced the hand-drawn ICONS.md marks
 * with one family: Iconsax icons generated by `npm run icons` into
 * `src/icons/`, at the app's one stroke. Every export here keeps the name it
 * had, so no caller moved in the same commit, and each one now draws
 * `<Icon name=... />` for the icon that means the same thing. New code imports
 * `Icon` directly; a later cleanup deletes these once their callers are gone.
 *
 * `close`, `check` and `alert` sit in `components.tsx`, beside the parts that
 * draw them: this file imports from that one (`SpeakerGlyph`), so the reverse
 * edge would be a cycle. `alert` is re-exported here, so a screen still finds
 * it with the other row marks. The right chevron is there too, beside the left.
 *
 * Every icon is decorative: the row it heads says what it is. `glyphs.test.ts`
 * and `motion.test.ts` hold the generated files to the one pen and to stillness.
 */

import type { MissionPlace } from '@luvani/core';
import { Icon } from './icons/Icon.tsx';
import { PLACE_ICON } from './icons/places.ts';
import { paper } from './theme.ts';

export interface GlyphProps {
  size?: number;
  color?: string;
}

/**
 * The speaker mark, which is the ear the tutor's voice already used.
 *
 * Re-exported rather than redrawn: a phrase card's round speaker button and the
 * "tutor is talking" ear are the same idea (sound arriving), and two drawings
 * of it would drift apart the first time one of them was nudged.
 */
export { EarGlyph as SpeakerGlyph } from './components.tsx';

/**
 * The alert, drawn in `components.tsx` because `Field` draws it beside its
 * error line, and importing it back from here would be a cycle. Callers still
 * reach it here, beside the other row marks (F601).
 */
export { AlertGlyph } from './components.tsx';

/** How long tonight's French takes. */
export function ClockGlyph({ size = 24, color = paper.ink }: GlyphProps) {
  return <Icon name="clock" size={size} color={color} />;
}

/** The everyday mission: a café cup. */
export function CoffeeCupGlyph({ size = 24, color = paper.ink }: GlyphProps) {
  return <Icon name="coffee" size={size} color={color} />;
}

/** Talking about anything: two bubbles in turn. */
export function ChatGlyph({ size = 24, color = paper.ink }: GlyphProps) {
  return <Icon name="chat" size={size} color={color} />;
}

/** A written conversation, and the phrasebook: ICONS.md drew a book here, and so does the set. */
export function DocumentGlyph({ size = 24, color = paper.ink }: GlyphProps) {
  return <Icon name="book" size={size} color={color} />;
}

/** Replay a moment, once more. */
export function ReplayGlyph({ size = 24, color = paper.ink }: GlyphProps) {
  return <Icon name="replay" size={size} color={color} />;
}

/** The phrase shelf: what the learner said, kept in quotes. */
export function QuoteGlyph({ size = 24, color = paper.ink }: GlyphProps) {
  return <Icon name="quote" size={size} color={color} />;
}

/** A voice seen sideways. */
export function WaveformGlyph({ size = 24, color = paper.ink }: GlyphProps) {
  return <Icon name="waveform" size={size} color={color} />;
}

/**
 * The mark for a place a conversation happens in, one per `MissionPlace`.
 *
 * `PLACE_ICON` is a `Record` over the union, so a seventh place with no icon is
 * a typecheck failure there and not a blank disc on a phone.
 */
export function PlaceGlyph({ place, size = 24, color = paper.ink }: GlyphProps & { place: MissionPlace }) {
  return <Icon name={PLACE_ICON[place]} size={size} color={color} />;
}

